t-size:5px;color:var(--muted);margin-top:2mm;word-break:break-all}.print-note{margin-top:24px;padding:12px;border-left:4px solid var(--yellow);background:#fff8df;font-size:10px;color:#625326}.print-note strong{display:block;margin-bottom:3px}@media(max-width:780px){.print-toolbar{align-items:flex-start;flex-direction:column}.toolbar-actions{width:100%}.toolbar-actions>*{flex:1}.credential-sheet{padding:15px}.print-grid{grid-template-columns:1fr}.pet-id-card{margin:auto}.sheet-heading{align-items:flex-start;flex-direction:column;gap:8px}}@media print{@page{size:A4 portrait;margin:12mm}body{background:#fff}.print-toolbar,.sheet-heading,.print-note{display:none!important}.credential-sheet{width:100%;min-height:0;margin:0;padding:0;box-shadow:none}.print-grid{grid-template-columns:1fr 1fr;gap:22mm}.credential-block>h2{display:none}.pet-id-card,.pet-tag{break-inside:avoid;print-color-adjust:exact;-webkit-print-color-adjust:exact}}
